// Runnable demo: pinball choreography (unobservable) vs orchestrated Saga (central).

import java.util.*;
import java.util.function.Consumer;
import java.util.logging.*;

public class LoanOrchestrationDemo {

    private static final Logger log = Logger.getLogger("loan");

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        VerificationService verify = new VerificationService();
        CreditScoreService score = new CreditScoreService();
        ApprovalService approve = new ApprovalService();
        DisbursementService disburse = new DisbursementService();

        log.info("===== PINBALL CHOREOGRAPHY (anti-pattern) =====");
        PinballChoreography pinball = new PinballChoreography(verify, score, approve, disburse);
        pinball.start("LOAN-1", "SAV2001");
        // Try to answer "what state is LOAN-1 in?" — nobody knows.
        log.severe("[STATUS] where is LOAN-1? → UNKNOWN (no component holds the state)");

        log.info("===== ORCHESTRATED SAGA (fix: central state machine) =====");
        LoanOrchestrator orchestrator = new LoanOrchestrator(verify, score, approve, disburse, /*disburseFails*/ true);
        orchestrator.process("LOAN-2", "SAV2001");
        log.info(() -> "[STATUS] LOAN-2 state = " + orchestrator.getState("LOAN-2") + " (queryable!)");
    }
}

// ─── model/LoanState.java ───
enum LoanState { STARTED, VERIFIED, SCORED, APPROVED, DISBURSED, COMPENSATING, CANCELLED, COMPLETED }

// ─── service classes ───
class VerificationService { private static final Logger log = Logger.getLogger("loan");
    void verify(String id) { log.info(() -> "[VERIFY] " + id); } }
class CreditScoreService { private static final Logger log = Logger.getLogger("loan");
    void score(String id) { log.info(() -> "[SCORE] " + id); } }
class ApprovalService { private static final Logger log = Logger.getLogger("loan");
    void approve(String id) { log.info(() -> "[APPROVE] " + id); }
    void revoke(String id) { log.warning(() -> "[APPROVE] compensate revoke " + id); } }
class DisbursementService { private static final Logger log = Logger.getLogger("loan");
    void reserveFunds(String id) { log.info(() -> "[FUNDS] reserved for " + id); }
    void releaseFunds(String id) { log.warning(() -> "[FUNDS] compensate release for " + id); }
    void disburse(String id, boolean fail) {
        if (fail) { log.severe(() -> "[DISBURSE] FAILED for " + id); throw new RuntimeException("disbursement error"); }
        log.info(() -> "[DISBURSE] done for " + id);
    } }

// ─── pinball/LoanEventBus.java ───
class LoanEventBus {
    private final List<Consumer<String[]>> subs = new ArrayList<>();
    void subscribe(Consumer<String[]> s) { subs.add(s); }
    void publish(String type, String id) { subs.forEach(s -> s.accept(new String[]{type, id})); }
}

// ─── pinball/PinballChoreography.java — ANTI-PATTERN ───
class PinballChoreography {
    private static final Logger log = Logger.getLogger("loan");
    private final VerificationService verify; private final CreditScoreService score;
    private final ApprovalService approve; private final DisbursementService disburse;
    private final LoanEventBus bus = new LoanEventBus();
    PinballChoreography(VerificationService v, CreditScoreService s, ApprovalService a, DisbursementService d) {
        verify = v; score = s; approve = a; disburse = d;
        bus.subscribe(this::onEvent);   // complex flow bounces through events, no coordinator
    }
    void start(String id, String account) { verify.verify(id); bus.publish("Verified", id); }
    private void onEvent(String[] e) {
        String type = e[0], id = e[1];
        switch (type) {
            case "Verified" -> { score.score(id); bus.publish("Scored", id); }
            case "Scored" -> { approve.approve(id); bus.publish("Approved", id); }
            case "Approved" -> { disburse.reserveFunds(id); bus.publish("FundsReserved", id); }
            case "FundsReserved" -> {
                try { disburse.disburse(id, true); }
                catch (RuntimeException ex) {
                    // Scattered compensation: this one service guesses the rollback, in the wrong place.
                    log.severe(() -> "[PINBALL] disbursement failed — compensation logic scattered, order unclear");
                }
            }
            default -> { }
        }
    }
}

// ─── orchestration/LoanOrchestrator.java — central state machine ───
class LoanOrchestrator {
    private static final Logger log = Logger.getLogger("loan");
    private final VerificationService verify; private final CreditScoreService score;
    private final ApprovalService approve; private final DisbursementService disburse;
    private final boolean disburseFails;
    private final Map<String, LoanState> states = new HashMap<>();   // durable, queryable
    LoanOrchestrator(VerificationService v, CreditScoreService s, ApprovalService a, DisbursementService d, boolean fail) {
        verify = v; score = s; approve = a; disburse = d; disburseFails = fail;
    }
    void process(String id, String account) {
        states.put(id, LoanState.STARTED);
        try {
            verify.verify(id);         states.put(id, LoanState.VERIFIED);
            score.score(id);           states.put(id, LoanState.SCORED);
            approve.approve(id);       states.put(id, LoanState.APPROVED);
            disburse.reserveFunds(id);
            disburse.disburse(id, disburseFails);  states.put(id, LoanState.DISBURSED);
            states.put(id, LoanState.COMPLETED);
        } catch (RuntimeException ex) {
            states.put(id, LoanState.COMPENSATING);
            log.severe(() -> "[ORCH] disbursement failed → central ordered compensation");
            disburse.releaseFunds(id);   // reverse order, in ONE place
            approve.revoke(id);
            states.put(id, LoanState.CANCELLED);
        }
    }
    LoanState getState(String id) { return states.get(id); }   // answer status anytime
}

